  ngOnInit() {
    const formGroup: { [key: string]: FormControl } = {};
    this.formFields.forEach(field => {
      formGroup[field.name] = new FormControl('', field.validators);
    });

    this.contactFormD = new FormGroup(formGroup);
  }

